<?php namespace Workspace; ?>
<p>Сводка по всем доступным владельцу срокам, независимо от личных подписок. Расчёт на <?= h(gmdate('Y-m-d H:i:s',$now)) ?> UTC. Счета учитываются только при непогашенном остатке; реакция на инцидент — до подтверждения реакции.</p>
<section class="panel inset"><form method="get" class="inline"><input type="hidden" name="p" value="digest"><label>Проект<select name="project"><?php selectOptions([''=>'Все проекты']+$projects,$project??'') ?></select></label><label>Горизонт, дней<input type="number" name="horizon" min="0" max="90" value="<?= h($horizon) ?>" required></label><button>Обновить</button></form><p><a href="<?= h(url('notifications',['project'=>$project??''])) ?>">Личные напоминания</a></p></section>
<?php foreach($labels as $k=>$label): ?><section class="panel"><h2><?= h($label) ?></h2><?php if(isset($errors[$k])): ?><p class="notice"><?= h($errors[$k]) ?> Данные не включены в итог.</p><?php elseif(empty($summary[$k])): ?><p class="empty">Нет сроков в выбранном горизонте.</p><?php else: ?><p>Просрочено: <?= h(array_sum(array_column($summary[$k],'overdue'))) ?> · всего в горизонте: <?= h(array_sum(array_column($summary[$k],'total'))) ?></p><table><thead><tr><th>Проект</th><th>Просрочено</th><th>До конца горизонта (включая просрочку)</th></tr></thead><tbody><?php foreach($summary[$k] as $r): ?><tr><td><a href="<?= h(url('project',['id'=>$r['project_id']])) ?>"><?= h($r['project_title']) ?></a></td><td><?= h($r['overdue']) ?></td><td><?= h($r['total']) ?></td></tr><?php endforeach ?></tbody></table><?php endif ?></section><?php endforeach ?>
